INSERT INTO public.hanja_dict (hanja, korean, meaning, updated_at)
VALUES
  ('七步才', '칠보재', '일곱 걸음 걷는 사이에 시 한 수를 짓는 재능이라는 뜻으로, 걸작의 시문을 빨리 짓는 재주를 이름. 위(魏)나라 문제(文帝) 조비(曹丕)가 그의 아우 조식(曹植)을 꺼려서 ‘일곱 걸음 걷는 동안에 시 한 수를 지어라. 만일 못 지으면 처형하겠다.’고 명하니, 조식이 즉석에서 ‘煮豆持作羹, 漉菽以爲汁, 其在釜下然, 豆在釜中泣, 本是同根生, 相煎何太急’이라는 시를 지어, 형으로서 아우를 죽이는 것은 너무 무정한 일이라고 풍자한 고사(故事)에서 나온 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七佛', '칠불', '[불교] 과거에 나타난 일곱 부처. 곧, 비바시(毘婆尸)·시기(尸棄)·비사부(毘舍浮)·구류손(拘留孫)·구나함모니(俱那含牟尼)·가섭(迦葉)·석가(釋迦).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七佛藥師', '칠불약사', '[불교] 약사여래(藥師如來)가 중생(衆生)을 제도(濟度)하기 위하여 변화분신(變化分身)하여 나타나는 일곱 불체(佛體). 곧, 선칭명길상왕여래(善稱名吉祥王如來)·보월지엄광음자재왕여래(寶月智嚴光音自在王如來)·금색보광묘행성취여래(金色寶光妙行成就如來)·무우최승길상여래(無憂最勝吉祥如來)·법해뇌음여래(法海雷音如來)·법해승혜유희신도여래(法海勝慧遊戲神通如來)·약사유리광여래(藥師瑠璃光如來).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七死七生', '칠사칠생', '[불교] 일곱 번 죽고 일곱 번 다시 태어남.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七色', '칠색', '일곱 가지 빛. 곧, 적(赤)·청(靑)·황(黃)·녹(綠)·자(紫)·감(紺)·화(樺).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七生', '칠생', '[불교] 일곱 번 다시 태어남. 몇 번이고 다시 태어남. 이 세상에 다시 태어날 수 있는 한 영원히 언제까지나의 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七書', '칠서', '① 삼경(三經)과 사서(四書). 곧, 주역(周易)·서경(書經)·시경(詩經)·논어(論語)·맹자(孟子)·중용(中庸)·대학(大學). ② 일곱 가지 병서(兵書). 곧, 손자(孫子)·오자(吳子)·사마법(司馬法)·울료자(尉繚子)·삼략(三略)·육도(六韜)·이위공문대(李衛公問對). 무경칠서(武經七書).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七夕', '칠석', '명절의 하나. 음력 칠월 초이렛날. 이날 저녁에 은하(銀河) 동쪽에 있는 견우성(牽牛星)이 서쪽에 있는 직녀성(織女星)과 오작교(烏鵲橋)에서 만난다고 함. 고래로 이날 걸교전(乞巧奠)을 행하는 풍습이 있음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七星', '칠성', '① 북두칠성(北斗七星). ② 피부에 난 일곱 개의 별 모양으로 된 점.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七聲', '칠성', '칠음(七音) ①.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七星劍', '칠성검', '춘추 시대(春秋時代)의 초(楚)나라 사람 오자서(伍子胥)가 차던 명검(名劍).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七順', '칠순', '덕(德)을 높이는 일곱 가지 순종(順從)하는 도(道). 곧, 순천(順天)·순지(順地)·순민(順民)·순리(順利)·순덕(順德)·순인(順仁)·순도(順道).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七十二疑冢', '칠십이의총', '위(魏)나라의 조조(曹操)가 죽은 후에 자기의 무덤을 발굴당할까 염려하여 가짜로 만든 일흔두 기(基)의 무덤.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七十二弟子', '칠십이제자', '공자(孔子)의 제자 중에서 육예(六藝)에 통한 일흔두 사람의 일컬음. 일설(一說)에는, 일흔일곱 사람이라고도 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七十二候', '칠십이후', '1년의 기후를 일흔둘로 나눈 것의 일컬음. 오일(五日)을 일후(一候), 삼후(三候)를 일기(一氣), 육후(六候)를 1개월로 함. 칠십이후의 이름은 다음 표와 같음.</br></br>| 月名 | 二十四氣 | 七十二候 |</br>| :---: | :---: | :--- |</br>| 正月 | 立春 | 東風解凍. 蟄蟲始振. 魚上氷. |</br>| 正月 | 雨水 | 獺祭魚. 鴻雁來. 草木萌動. |</br>| 二月 | 驚蟄 | 桃始華. 倉庚鳴. 鷹化爲鳩. |</br>| 二月 | 春分 | 玄鳥至. 雷乃發聲. 始電. |</br>| 三月 | 淸明 | 桐始華. 田鼠化爲鴽. 虹始見. |</br>| 三月 | 穀雨 | 萍始生. 鳴鳩拂其羽. 戴勝降于桑. |</br>| 四月 | 立夏 | 螻蟈鳴. 蚯蚓出. 王瓜生. |</br>| 四月 | 小滿 | 苦菜秀. 靡艸死. 麥秋至. |</br>| 五月 | 芒種 | 螳螂生. 鵙始鳴. 反舌無聲. |</br>| 五月 | 夏至 | 鹿角解. 蜩始鳴. 半夏生. |</br>| 六月 | 小暑 | 溫風始至. 蟋蟀居壁. 鷹乃學習. |</br>| 六月 | 大暑 | 腐艸爲螢. 土潤溽暑. 大雨時行. |</br>| 七月 | 立秋 | 涼風至. 白露降. 寒蟬鳴. |</br>| 七月 | 處暑 | 鷹祭鳥. 天地始肅. 禾乃登. |</br>| 八月 | 白露 | 鴻雁來. 玄鳥歸. 羣鳥養羞. |</br>| 八月 | 秋分 | 雷始收聲. 蟄蟲坏戶. 水始涸. |</br>| 九月 | 寒露 | 鴻雁來賓. 爵入大水爲蛤. 鞠有黃華. |</br>| 九月 | 霜降 | 豺乃祭獸戮禽. 草木黃落. 蟄蟲咸俯. |</br>| 十月 | 立冬 | 水始氷. 地始凍. 雉入大水爲蜃. |</br>| 十月 | 小雪 | 虹藏不見. 天氣上騰, 地氣下降. 閉塞而成冬. |</br>| 十一月 | 大雪 | 鴠旦不鳴. 虎始交. 荔挺出. |</br>| 十一月 | 冬至 | 蚯蚓結. 麋角解. 水泉動. |</br>| 十二月 | 小寒 | 雁北鄕. 鵲始巢. 雉始雊. |</br>| 十二月 | 大寒 | 雞乳. 征鳥厲疾. 水澤腹堅. |', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七十子', '칠십자', '칠십이 제자(七十二弟子).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七言', '칠언', '한 구(句)가 일곱 자로 된 한시(漢詩).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七言古詩', '칠언고시', '칠언(七言)으로 된 고시(古詩). 구(句)의 수가 일정하지 아니함. 항우(項羽)의 ‘해하가(垓下歌)’, 한고조(漢高祖)의 ‘대풍가(大風歌)’ 따위. 칠고(七古).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七言古風', '칠언고풍', '칠언 고시(七言古詩).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七言排律', '칠언배율', '칠언 율시(七言律詩)의 연구(聯句) 여섯 구 이상으로 된 한시(漢詩).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七言律詩', '칠언율시', '칠언(七言) 여덟 구로 되고, 제3구·제4구와 제5구·제6구가 대구(對句)를 이룬 한시(漢詩). 칠률(七律).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七言絶句', '칠언절구', '칠언(七言) 네 구로 된 한시(漢詩). 칠절(七絶).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七葉', '칠엽', '일곱 대(代). 칠세(七世).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七曜', '칠요', '① 해·달과, 화(火)·수(水)·목(木)·금(金)·토(土)의 다섯 별. 칠정(七政). ② 일주일. 이레에 칠요(七曜)를 할당한 일컬음. 곧, 일요·월요·화요·수요·목요·금요·토요.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七曜星', '칠요성', '북두성(北斗星).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七雄', '칠웅', '전국 시대(戰國時代)의 일곱 강국(强國). 곧, 진(秦)·초(楚)·연(燕)·제(齊)·조(趙)·위(魏)·한(韓). 웅(雄)은 수장(首長)의 뜻임. 칠국(七國).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七緯', '칠위', '① 해·달과, 화·수·목·금·토의 다섯 별. ② 일곱 가지 위서(緯書). 곧, 역위(易緯)·서위(書緯)·시위(詩緯)·예위(禮緯)·악위(樂緯)·춘추위(春秋緯)·효경위(孝經緯).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七音', '칠음', '① 음악의 일곱 가지 가락. 곧, 궁(宮)·상(商)·각(角)·치(徵)·우(羽)의 오음(五音)과 반치(半徵)·반상(半商). ② 음운상(音韻上)에 있어서의 일곱 가지 성음(聲音). 곧, 순음(脣音)·설음(舌音)·아음(牙音)·치음(齒音)·후음(喉音)·반설음(半舌音)·반치음(半齒音).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七才子', '칠재자', '① 명(明)나라의 재치 있는 시인(詩人) 일곱 사람. 곧, 이몽양(李夢陽)·하경명(何景明)·서정경(徐禎卿)·변공(邊貢)·강해(康海)·왕구사(王九思)·왕정상(王廷相). ② 명나라의 재사(才士) 일곱 사람. 곧, 왕세정(王世貞)·이반룡(李攀龍)·사진(謝榛)·종신(宗臣)·양유예(梁有譽)·서중행(徐中行)·오국륜(吳國倫).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七顚八倒', '칠전팔도', '① 일어났다가는 넘어지고, 또 일어났다가는 넘어져 마침내 일어나지 못함. ② 고통을 참지 못하여 몸부림을 침. ③ 분란(紛亂)이 심함. 대단히 어지러움.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七絶', '칠절', '① 칠언 절구(七言絶句)의 약칭(略稱). ② 절구(絶句) 일곱 수(首).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七政', '칠정', '① 해·달과, 화·수·목·금·토의 다섯 별. 그 운행이 절도(節度)가 있어 국가의 정사(政事)와 비슷하므로 이름. ② 북두칠성(北斗七星). 칠성(七星). ③ 이십팔수(二十八宿) 중의 사방에 각각 일곱씩 있는 별.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七情', '칠정', '일곱 가지 감정(感情). 유학(儒學)에서는 희(喜)·노(怒)·애(哀)·구(懼)·애(愛)·오(惡)·욕(欲), 또는 희·노·애·낙(樂)·애·오·욕. 불가(佛家)에서는 희(喜)·노(怒)·우(憂)·구(懼)·애(愛)·증(憎)·욕(欲).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七條', '칠조', '[불교] 삼의(三衣)의 하나. 일곱 폭(幅)으로 만든 가사(袈裟).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七族', '칠족', '증조·조부·부친·자기·아들·손자·증손.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七宗', '칠종', '[불교] 율(律)·법상(法相)·삼론(三論)·화엄(華嚴)·천태(天台)·진언(眞言)·선(禪)의 일곱 종파(宗派).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七縱七擒', '칠종칠금', '적(敵)을 일곱 번 석방하였다가 일곱 번 사로잡음. 제갈공명(諸葛孔明)이 맹획(孟獲)을 사로잡은 고사(故事). 금(擒)은 금(禽)으로도 씀.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七衆', '칠중', '[불교] 불제자(佛弟子)의 일곱 종류의 사람. 곧, 비구(比丘)·비구니(比丘尼)·사미(沙彌)·사미니(沙彌尼)·식사미니(式沙彌尼)·우바새(優婆塞)·우바이(優婆夷).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七重寶樹', '칠중보수', '[불교] 극락정토(極樂淨土)에 있다고 하는 일곱 줄로 늘어선 일곱 종류의 보수(寶樹). 곧, 금수(金樹)·은수(銀樹)·유리수(瑠璃樹)·파리수(玻璃樹)·산호수(珊瑚樹)·마노수(瑪瑙樹)·거거수(硨磲樹).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七支', '칠지', '[불교] 십악(十惡) 중에서 살생(殺生)·투도(偸盜)·사음(邪淫)·망어(妄語)·기어(綺語)·악구(惡口)·양설(兩舌)의 일곱 가지. 십악(十惡)에서 갈려 나간 것이므로 지(支)라 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七志', '칠지', '① 책(冊)의 분류법(分類法)의 한 가지. 곧, 경전(經典)·제자(諸子)·문한(文翰)·군서(軍書)·음양(陰陽)·예술(藝術)·도보(圖譜). ② 송(宋)나라 사람 왕검(王儉)이 유흠(劉歆)의 칠략(七略)을 본떠 작성하고, 도불편(道佛篇)을 부록(附錄)으로 한 책.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七珍', '칠진', '칠보(七寶).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七秩', '칠질', '일흔 살. 70세. 일질(一秩)은 10년.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七札', '칠찰', '갑옷미늘 일곱 매(枚).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七尺去不蹋師影', '칠척거부답사영', '제자(弟子) 된 자는 항상 스승을 존경하여 수행(隨行)할 때에도 스승의 그림자를 밟지 않도록 조심하라는 훈계.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七尺之軀', '칠척지구', '신장이 7척 되는 몸.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七出', '칠출', '칠거(七去).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七七', '칠칠', '사람이 죽은 지 49일째 되는 날을 이름. 중음(中陰).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七香車', '칠향차', '일곱 가지 향나무로 만든 수레.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七香車', '칠향거', '일곱 가지 향나무로 만든 수레.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七賢', '칠현', '① 춘추 시대(春秋時代)의 일곱 현인(賢人). 곧, 백이(伯夷)·숙제(叔齊)·우중(虞仲)·이일(夷逸)·주장(朱張)·소련(少連)·유하혜(柳下惠). ② ‘죽림칠현(竹林七賢)’과 같음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七絃琴', '칠현금', '일곱 줄로 된 거문고.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('七花八裂', '칠화팔렬', '여러 갈래로 갈라짐. 산산조각이 남.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三', '삼', '[자해]</br>①석 삼 셋. ‘三冬’. ‘不孝有三’〈孟子〉.</br>②세번 삼 3회. ‘三拜’. ‘三思而後行’〈論語〉.</br>③성 삼 성(姓)의 하나.</br>④자주 삼 여러 번. ‘湯三使往聘之’〈孟子〉.</br></br>[자원] (갖은자: 參, 지사(指事))</br>세 개의 가로획으로 수(數)의 ‘셋’의 뜻을 나타냄.</br></br>[참고]</br>특히 금전상(金錢上)의 숫자 표시에서 그 변개(變改)를 막기 위해 ‘參’을 갖은자로 씀.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三加', '삼가', '가관(加冠)의 예(禮). 먼저 치포관(緇布冠)을 쓰고, 다음에 피변(皮弁)을 가(加)하고, 그 다음에 작변(爵弁)을 가하므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三家', '삼가', '춘추 시대(春秋時代)의 노(魯)나라의 삼대부(三大夫). 곧, 맹손씨(孟孫氏)·숙손씨(叔孫氏)·계손씨(季孫氏). 삼환(三桓).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三駕', '삼가', '세 번 군사를 일으킴.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三迦葉', '삼가섭', '[불교] 우루빈라가섭(優樓頻螺迦葉)·나제가섭(那提迦葉)·가야가섭(伽耶迦葉)의 삼 형제. 불〔火〕을 숭배하는 교(敎)인 사회외도(事火外道)의 수장(首長)인데, 후에 석가(釋迦)를 섬겼음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三角', '삼각', '세 모.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三恪', '삼각', '왕자(王者)가 선왕(先王)을 공경하는 일. 주(周)나라의 무왕(武王)이 우(虞)·하(夏)·은(殷) 삼대(三代)의 후손(後孫)을 봉(封)하여 ‘三恪’이라 한 고사(故事)에서 나옴. 恪(각)은 敬(경)의 뜻임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三覺', '삼각', '[불교] ① 본각(本覺)·시각(始覺)·구경각(究竟覺). ② 자각(自覺)·타각(他覺)·각행원만(覺行圓滿).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三角關係', '삼각관계', '① 세 사람 또는 세 단체 사이의 관계. ② 남녀 관계에 있어서 일남 이녀(一男二女) 혹은 이남 일녀(二男一女) 사이에 맺어진 연애(戀愛) 관계.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三角同盟', '삼각동맹', '삼국(三國) 또는 삼자의 동맹(同盟).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三角法', '삼각법', '삼각형(三角形)의 변(邊)과 각(角)과의 관계를 연구하는 수학(數學).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三角鬚', '삼각수', '두 뺨과 턱에 세 갈래로 난 수염.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三角形', '삼각형', '① 세모진 형상. ② 세 개의 직선(直線)으로 된 평면형(平面形). 세모꼴.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三竿', '삼간', '대나무 장대 셋가량을 이은 길이. 정오(正午)경에 해가 높이 뜸을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三監', '삼감', '① 주(周)나라 무왕(武王)이 은(殷)나라의 유민(遺民)을 주왕(紂王)의 아들 무경(武庚)에게 다스리게 하고 그를 감독하게 한 세 사람. 곧, 관숙(管叔)·채숙(蔡叔)·곽숙(霍叔). ② 옛날에 제후(諸侯)의 나라를 감독하기 위하여 각 나라마다 둔 세 사람의 벼슬아치. ③ [불교] 유교(儒敎)의 삼종(三從)과 뜻이 같음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三鑑', '삼감', '동경(銅鏡)을 보면 의관(衣冠)을 단정히 할 수 있고, 고대(古代)를 거울 삼으면 흥체(興替)를 알 수 있으며, 사람을 거울 삼으면 득실(得失)을 알 수 있으므로 이 셋을 세 거울이라고 이른 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三江', '삼강', '장쑤 성(江蘇省)의 대호(大湖)에서 흘러 내려가는 송강(松江)·누강(婁江)·동강(東江), 또는, 오송강(吳淞江)·전당강(錢塘江)·포양강(浦陽江).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三綱', '삼강', '유교(儒敎)의 도덕(道德)에 있어서 기본 되는 세 가지 강(綱)으로서 임금과 신하, 어버이와 자식, 남편과 아내 사이에 마땅히 지켜야 할 도리. 곧, 군위신강(君爲臣綱)·부위자강(父爲子綱)·부위부강(夫爲婦綱).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三綱領', '삼강령', '‘삼강령팔조목(三綱領八條目)’을 보라.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三綱領八條目', '삼강령팔조목', '대학(大學) 한 편(篇)의 정신인 명명덕(明明德)·친민(親民)·지어지선(止於至善)의 삼강령과 격물(格物)·치지(致知)·성의(誠意)·정심(正心)·수신(修身)·제가(齊家)·치국(治國)·평천하(平天下)의 팔조목.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三綱五倫', '삼강오륜', '삼강과 오륜. 오륜은 군신유의(君臣有義)·부자유친(父子有親)·부부유별(夫婦有別)·장유유서(長幼有序)·붕우유신(朋友有信).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三綱五常', '삼강오상', '삼강과 오상. 강상(綱常). 오상은 인(仁)·의(義)·예(禮)·지(智)·신(信).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三愆', '삼건', '어른을 모실 때의 세 가지 과실(過失). 곧, 묻기도 전에 말함〔躁〕, 물어도 대답하지 않음〔隱〕, 안색도 살피지 않고 멋대로 말함〔瞽〕. 〈논어(論語)〉에 나옴.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三傑', '삼걸', '세 사람의 뛰어난 인물. 곧, 한(漢)나라의 소하(蕭何)·장량(張良)·한신(韓信).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三更', '삼경', '하룻밤을 다섯으로 나눈 셋째의 경(更). 곧, 자정(子正) 전후.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三庚', '삼경', '삼복(三伏).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三徑', '삼경', '은사(隱士)의 문정(門庭). 한(漢)나라의 은사 장후(蔣詡)의 정원(庭園)에 좁은 길이 셋 있던 고사(故事)에서 나온 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三卿', '삼경', '주대(周代)의 세 벼슬. 곧, 사도(司徒)·사마(司馬)·사공(司空).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三經', '삼경', '세 경서(經書). ① 주역(周易)·시경(詩經)·춘추(春秋). ② 서경(書經)·시경(詩經)·주례(周禮). ③ 시경(詩經)·서경(書經)·주역(周易). ④ 논어(論語)·맹자(孟子)·대학(大學) 및 중용(中庸).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三戒', '삼계', '① 일생에 지켜야 할 세 가지 계(戒). 곧, 청년 시대에는 여색을, 장년(壯年) 시대에는 투쟁을, 노년 시대에는 이욕(利慾)을 경계하라는 공자(孔子)의 교훈. ② [불교] 재가계(在家戒)·출가계(出家戒)·도속공수계(道俗共守戒)의 세 가지 계.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三季', '삼계', '하(夏)·은(殷)·주(周) 삼대(三代)의 계세(季世).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三計', '삼계', '1년·10년·종신(終身)을 목표로 한 계획. 곧, 수곡(樹穀)·수목(樹木)·수인(樹人).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三界', '삼계', '[불교] ① 중생(衆生)이 생사(生死)·윤회(輪廻)하는 삼종(三種)의 세계(世界). 곧, 욕계(慾界)·색계(色界)·무색계(無色界). ② 과거·현재·미래의 삼세계(三世界). 삼세(三世). ③ 삼천 세계(三千世界).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三階', '삼계', '삼층(三層).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三界一心', '삼계일심', '[불교] 삼계(三界)는 모두 마음의 현상(現象)으로서 마음 외에 물질이 없다는 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三界火宅', '삼계화택', '[불교] 삼계(三界)는 화염(火炎)에 싸인 집과 같아서 고뇌(苦惱)가 한이 없다는 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三古', '삼고', '고대(古代)를 셋으로 나눈 상고(上古)·중고(中古)·하고(下古)의 일컬음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三考', '삼고', '벼슬아치의 정적(政績)을 9년간에 세 번 조사하여, 그 사람의 현부(賢否)·득실(得失)을 상고함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三孤', '삼고', '주대(周代)에 천자(天子)를 보좌하던 삼공(三公) 다음가는 벼슬. 곧, 소사(少師)·소부(少傅)·소보(少保). 삼소(三少).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三苦', '삼고', '[불교] 고(苦)의 인연(因緣)에서 생기는 고고(苦苦)와 즐거움이 깨져 생기는 괴고(壞苦)와 무상(無常)에서 생기는 행고(行苦).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三鼓', '삼고', '① 북·갈고(鞨鼓)·종고(鐘鼓). ② 삼경(三更).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三顧', '삼고', '촉한(蜀漢)의 임금 유비(劉備)가 제갈공명(諸葛孔明)의 집을 세 번 찾은 고사(故事). 전(轉)하여, 군주나 장상(長上)에게 특별한 신임이나 우대를 받는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三骨', '삼골', '[한국] 신라(新羅) 시대의 왕족(王族)과 귀족의 세 가지 혈통. 곧, 성골(聖骨)·진골(眞骨)·제이골(第二骨).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三公', '삼공', '① 가장 높은 세 가지 벼슬. 곧, 주(周)나라의 태사(太師)·태부(太傅)·태보(太保). 전한(前漢)의 승상(丞相)·태위(太尉)·어사대부(御史大夫). 후(後)에 대사도(大司徒)·대사마(大司馬)·대사공(大司空)으로 개칭. 후한(後漢)의 태위(太尉)·사도(司徒)·사공(司空). ② [한국] 조선 시대의 가장 높은 세 가지 벼슬. 곧, 영의정(領議政)·좌의정(左議政)·우의정(右議政)의 삼정승(三政丞).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三空', '삼공', '[불교] 아공(我空)·법공(法空)·아법이공(我法二空).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三公九卿', '삼공구경', '[한국] 조선 시대의 삼정승(三政丞)과 구경(九卿). 곧, 영의정(領議政)·좌의정(左議政)·우의정(右議政), 의정부 좌우참찬(議政府左右參贊)·육조 판서(六曹判書)·한성 판윤(漢城判尹)을 이름. 삼괴구극(三槐九棘).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三公六卿', '삼공육경', '[한국] 조선 시대의 영의정(領議政)·좌의정(左議政)·우의정(右議政)과 육조(六曹)의 각 판서(判書).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三公兄', '삼공형', '[한국] 조선 시대의 각 고을의 호장(戶長)·이방(吏房)·수형리(首刑吏)의 세 관속(官屬).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三過', '삼과', '[불교] 몸〔身〕·입〔口〕·뜻〔意〕이 저지르는 세 가지 과실.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三寡', '삼과', '양생법(養生法)의 하나. 사려(思慮)를 적게 하여 신(神)을 쉬게 하고, 기욕(嗜欲)을 적게 하여 정(精)을 쌓으며, 언어(言語)를 적게 하여 기(氣)를 기르는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三觀', '삼관', '[불교] 공(空)·가(假)·중(中)의 삼제(三諦)를 관찰하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三光', '삼광', '일(日)·월(月)·성(星)의 세 빛. 삼정(三精).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三魁', '삼괴', '과거(科擧)에 첫째로 급제한 장원(壯元)과 둘째로 급제한 방안(榜眼)과 셋째로 급제한 탐화(探花)의 일컬음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三槐', '삼괴', '① 주대(周代)에 외조(外朝)에 심은 홰나무 세 그루. ② 삼공(三公)이 이 세 그루의 홰나무를 향하여 앉았으므로 삼공(三公)을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三槐九棘', '삼괴구극', '삼공구경(三公九卿).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三敎', '삼교', '유교(儒敎)·불교(佛敎)·도교(道敎)의 세 교(敎).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三丘', '삼구', '삼신산(三神山).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三垢', '삼구', '[불교] 탐욕(貪欲)·진에(瞋恚)·우치(愚癡). 삼독(三毒).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三驅', '삼구', '① 옛날에 천자(天子)가 사냥을 할 때 삼면(三面)을 터놓고 오직 한 방면에서 오는 조수(鳥獸)만을 잡던 일. ② 사냥의 예절(禮節).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三九之位', '삼구지위', '삼공구경(三公九卿)의 지위.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三國', '삼국', '① 후한말(後漢末)에 일어난 촉(蜀)·위(魏)·오(吳)의 세 나라. ② [한국] 신라(新羅)·고구려(高句麗)·백제(百濟)의 세 나라.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三國鼎立', '삼국정립', '세 나라가 솥발과 같이 서로 대립함. 삼분정족(三分鼎足).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三國志', '삼국지', '진(晉)나라 진수(陳壽)가 편찬한 삼국 시대(三國時代)의 역사책. 위지(魏志)는 30권, 촉지(蜀志)는 15권, 오지(吳志)는 20권으로 모두 65권임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三軍', '삼군', '① 주대(周代)에 대제후(大諸侯)가 소유한 상군(上軍)·중군(中軍)·하군(下軍)의 일컬음. 각 군은 12,500명임. ② 다수의 군대. 대군(大軍). ③ 전군(全軍). ④ 육군·해군·공군의 총칭.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三軍可奪帥也匹夫不可奪志也', '삼군가탈수야필부불가탈지야', '삼군(三軍)은 군사의 수효가 대단히 많으나, 각자의 마음이 일치하지 않으면 그 장수를 빼앗을 수도 있는데, 필부(匹夫)는 비록 미력(微力)한 사람이지만 그의 지조가 굳으면 그 지조를 빼앗을 수 없다는 뜻으로, 지조의 존엄성(尊嚴性)을 강조한 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三軍門', '삼군문', '조선 시대의 훈련도감(訓鍊都監)·금위영(禁衛營)·어영청(御營廳)의 세 군문. 삼영문(三營門).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三宮', '삼궁', '명당(明堂)·벽옹(辟雍)·영대(靈臺).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三窮', '삼궁', '사람이 궁하면 거짓말을 하고, 짐승이 궁하면 움켜쥐고, 새가 궁하면 쫌.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三權', '삼권', '국가 통치(統治)의 세 가지 권력. 곧, 입법권(立法權)·행정권(行政權)·사법권(司法權).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三歸', '삼귀', '① 아내를 셋 두는 일. 귀(歸)는 가(嫁). ② 관중(管仲)이 지은 대사(臺榭) 이름. ③ [불교] 불(佛)·법(法)·승(僧)의 삼보(三寶)에 귀의(歸依)하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三極', '삼극', '하늘과 땅과 사람. 천(天)·지(地)·인(人). 삼재(三才).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三器', '삼기', '① 나라를 다스리는 데 필요한 세 가지 권력. 곧, 호령(號令)·부월(斧鉞)·녹상(祿賞). ② 천문(天文)을 관측하는 데 필요한 세 가지 기구. 곧, 혼천의(渾天儀)·동후의(銅候儀)·혼천상(渾天象).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三南', '삼남', '[한국] 충청도(忠淸道)·전라도(全羅道)·경상도(慶尙道)의 세 도의 총칭.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年耕必有一年之食', '삼년경필유일년지식', '3년간 농사에 힘쓰면 1년간 먹을 양식을 저축할 수 있음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年大比', '삼년대비', '3년마다 지방의 벼슬아치나 처사(處士)의 재능을 조사하여 등용하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年無改於父之道可謂孝', '삼년무개어부지도가위효', '부친이 죽은 후 3년간 부친이 생전에 하던 일을 그대로 두고 조금도 변경하지 않는 것은 효도(孝道)라고 일컬을 수 있음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年不弔', '삼년부조', '상기(喪期) 3년 동안에 조상(弔喪)을 하지 못하거나 아니함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年不窺園', '삼년불규원', '3년 동안이나 문 밖에 나가서 정원을 보지 않는다는 뜻으로, 방에 꼭 들어박혀 학문에 열중함을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年不蜚', '삼년불비', '새가 3년 동안이나 날지 않는다는 뜻으로, 사람이 후일에 웅비(雄飛)할 기회를 기다림을 이름. ‘일명경인(一鳴驚人)’을 참고하라.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年喪', '삼년상', '삼년지상(三年之喪).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年有成', '삼년유성', '나를 써서 나라를 다스리게 한다면 3년 후에는 치적(治績)을 올려 반드시 성취(成就)하는 바가 있을 것이라고 공자(孔子)가 한 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年之喪', '삼년지상', '3년 동안의 거상(居喪). 곧, 부모의 거상.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三年通一經', '삼년통일경', '3년간 공부하여 경서(經書) 1권의 뜻에 통달함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三多', '삼다', '문장(文章)에 숙달(熟達)하는 세 가지 조건. 곧, 간다(看多)〈많이 읽는 일〉·주다(做多)〈많이 짓는 일〉·상량다(商量多)〈많이 구상하는 일〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三端', '삼단', '문사(文士)의 필단(筆端), 무사(武士)의 봉단(鋒端), 변사(辯士)의 설단(舌端). 모두 군자(君子)가 삼가야 할 것임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三段敎授', '삼단교수', '교수의 과정을 직관(直觀)·총괄(總括)·응용(應用)의 3단으로 나누어 가르치는 교수법.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三段論法', '삼단논법', '대전제(大前提)·소전제(小前提)·단안(斷案)의 3단으로 배열하여 추리하는 논리(論理)의 방식.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三達德', '삼달덕', '세 가지 높은 덕(德). 곧, 지(智)·인(仁)·용(勇).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三達尊', '삼달존', '세 가지 존귀한 것. 곧, 조정(朝廷)에서는 작위(爵位), 향리(鄕里)에서는 연령, 사회에서는 덕(德).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三大', '삼대', '[불교] 진여(眞如)의 체대(體大)〈본체〉·상대(相大)〈현상〉·용대(用大)〈작용〉의 세 가지. 진여는 광대하여 만물을 포용(包容)하므로 대(大)라 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三代', '삼대', '① 조부와 아비와 아들, 또는 아비와 아들과 손자의 세 대. ② 하(夏)·은(殷)·주(周)의 세 왕조(王朝).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三德', '삼덕', '① 정직(正直)·강극(剛克)·유극(柔克). ② 지(智)·인(仁)·용(勇). 삼달덕(三達德). ③ 지덕(至德)·민덕(敏德)·효덕(孝德). ④ 천덕(天德)·지덕(地德)·인덕(人德). ⑤ 삼정(三正)의 덕(德). ⑥ [불교] 은덕(恩德)〈여래(如來)가 중생을 구제하는 덕〉·단덕(斷德)〈여래가 일체의 번뇌를 끊는 덕〉·지덕(智德)〈여래가 평등(平等)의 지혜로 일체의 법(法)을 비추는 덕〉. ⑦ [불교] 법신덕(法身德)〈깨달음의 본체(本體)〉·반야덕(般若德)〈절대 평등의 슬기〉·해탈덕(解脫德)〈무애자재(無碍自在)의 덕〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三刀', '삼도', '고을주 자, 주(州)를 이름. 진(晉)나라 사람 왕준(王濬)이 어느 날 밤에 칼 석 자루를 들보에 걸어 놓았는데, 그날 밤 꿈에 칼 한 자루를 더 걸어 놓은 꿈을 꾸고 불길하게 생각하였으나, 주부(主簿) 이의(李毅)가 말하기를 삼도(三刀), 곧 ‘𠛱’는 고을주 자인데 한 칼을 더하니 익주(益州)가 된다. 그러니 자네가 익주의 태수(太守)가 될 길조(吉兆)일 것이라고 하였더니, 후에 과연 익주의 태수가 되었다는 고사(故事)에서 나온 말. 전(轉)하여 천관(遷官) 또는 영전의 뜻으로 쓰임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三到', '삼도', '독서하는 데 주의하여야 할 세 가지. 곧, 구도(口到)·안도(眼到)·심도(心到). 독서삼도(讀書三到).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三島', '삼도', '신선(神仙)이 산다는 봉래(蓬萊)·방장(方丈)·영주(瀛洲)의 세 섬. 삼신산(三神山).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三途', '삼도', '[불교] 화도(火途) 곧 지옥도(地獄道), 도도(刀途) 곧 아귀도(餓鬼道), 혈도(血途) 곧 축생도(畜生道)의 일컬음. 삼도(三塗).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三都', '삼도', '송(宋)나라의 개봉부(開封府)·귀덕부(歸德府)·하남부(河南府).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三道', '삼도', '삼행(三行) ①.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三塗', '삼도', '삼도(三途).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三塗川', '삼도천', '[불교] 지극히 악하지도 않고 지극히 착하지도 않은 사람이 죽은 후 저승으로 가는 도중에 건너는 내. 삼도내.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三毒', '삼독', '[불교] 사람의 성명(性命)에 해독이 되는 세 가지. 곧, 탐욕(貪慾)·진에(瞋恚)·우치(愚癡).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三冬', '삼동', '겨울의 석 달. 곧, 음력 시월의 맹동(孟冬), 동짓달의 중동(仲冬), 섣달의 계동(季冬).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三洞', '삼동', '도교(道敎)에서, 그 경전(經典)을 불교(佛敎)의 삼장(三藏)을 모방하여 나눈 것. 곧, 동진부(洞眞部)〈대승(大乘)〉·동현부(洞玄部)〈중승(中乘)〉·동신부(洞神部)〈소승(小乘)〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三斗塵', '삼두진', '많은 먼지.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三樂', '삼락', '군자의 세 가지 낙(樂). 곧, 부모가 모두 생존하고 형제가 무고함과, 하늘과 사람에게 부끄러워할 것이 없는 것과, 천하(天下)의 영재(英才)를 얻어 교육하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三略', '삼략', '한(漢)나라 사람 장량(張良)이 황석공(黃石公)에게서 받았다는 병서(兵書). 상략(上略)·중략(中略)·하략(下略)의 세 권으로 되었으며, 육도(六韜)와 병칭(倂稱)됨.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三靈', '삼령', '천(天)·지(地)·인(人)의 신령.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三令五申', '삼령오신', '자주 되풀이하여 훈령(訓令)을 내려 신칙한다는 뜻으로, 성의를 다하여 타이름을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三禮', '삼례', '고례(古禮)를 기록한 세 가지 책. 곧, 의례(儀禮)·주례(周禮)·예기(禮記).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三老', '삼로', '① 한 마을 중의 장로(長老). ② 연로(年老)하여 한 마을의 교화(敎化)를 맡은 사람. ③ 세 가지 노인. 곧, 공로(工老)·상로(商老)·농로(農老), 또, 상수(上壽)·중수(中壽)·하수(下壽). ④ 뱃사공.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三老五更', '삼로오경', '고대(古代)에 천자(天子)가 부형의 예로써 우대한 노인으로서 한 마을의 교화를 맡았음. 삼로(三老)와 오경(五更)이 각각 한 사람임. 일설(一說)에는, 삼로는 세 사람, 오경은 다섯 사람이라 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三論', '삼론', '[불교] 삼론종(三論宗)의 전거(典據)가 되는 세 가지 책. 곧, 용수보살(龍樹菩薩)이 지은 중론(中論)과 십이문론(十二門論) 및 그의 제자 제바(提婆)가 지은 백론(百論).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三倫', '삼륜', '군주(君主)와 관원(官員)과 근시(近侍)의 신하(臣下).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三輪', '삼륜', '[불교] ① 삼업(三業). ② 지하(地下)에서 대지(大地)를 받들고 있다는 금륜(金輪)과 수륜(水輪)과 풍륜(風輪).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三稜', '삼릉', '세 모서리. 세 모. 삼각(三角).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三稜鏡', '삼릉경', '광선을 분석(分析)하는 삼각주(三角柱)의 유리. 프리즘.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三稜筋', '삼릉근', '팔 윗마디 뼈와 어깻죽지를 연하여 팔뚝 위로 펴서 움직이게 하는 심줄. 삼각근(三角筋).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三稜針', '삼릉침', '세모진 침.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三吏', '삼리', '삼공(三公).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三利', '삼리', '세 가지 이익. 곧, 곡식을 심는 1년의 이익과 나무를 심는 10년의 이익과 덕(德)을 심는 100년의 이익.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三忘', '삼망', '장사(將士)가 출전(出戰)할 때 잊어야 할 세 가지 일. 곧, 망가(忘家)·망친(忘親)·망신(忘身).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三昧', '삼매', '[불교] 범어(梵語) samadhi의 음역(音譯). 오직 한 가지 일에만 마음을 집중시키는 경지(境地).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三昧境', '삼매경', '[불교] 삼매(三昧).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三昧堂', '삼매당', '[불교] 삼매(三昧)를 닦는 당(堂)이라는 뜻으로, 대개는 법화 삼매(法華三昧)·염불 삼매(念佛三昧)를 닦는 당을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三昧僧', '삼매승', '[불교] 법화 삼매(法華三昧) 또는 염불 삼매(念佛三昧)를 닦는 중.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三脈法', '삼맥법', '삼맥술(三脈術).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三脈術', '삼맥술', '오른손 또는 왼손의 맥박과 하악(下顎) 양측(兩側)의 맥박의 정부(整否)에 의하여 길흉(吉凶)을 점치는 술법.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三藐三菩提', '삼막삼보리', '[불교] 정편지(正遍智) 또는 정편각(正遍覺)이라 번역함. 죽음의 미혹(迷惑)을 버리고 빠짐없이 일체의 법(法)을 깨닫는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三明', '삼명', '① 해·달·별. 일(日)·월(月)·성(星). ② [불교] 아라한(阿羅漢)의 세 가지 밝은 지혜(智慧). 곧, 숙명통(宿命通)〈과거의 일에 통함〉·천안통(天眼通)〈미래의 일에 통함〉·누진통(漏盡通)〈현재의 일에 통함〉. ③ 후한(後漢)의 단기명(段紀明)·황보위명(皇甫威明)·장연명(張然明)의 세 사람. ④ 진(晉)나라의 제갈도명(諸葛道明)·순도명(荀道明)·채도명(蔡道明)의 세 사람.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三木', '삼목', '옛날의 형구(刑具) 세 가지. 곧, 머리와 손과 발에 끼우는 틀로서 우리나라의 칼·차꼬·족쇄 따위.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三苗', '삼묘', '요순 시대(堯舜時代)에 있던 남방의 오랑캐. 사흉(四凶)의 하나임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三廟', '삼묘', '① 세 사당(祠堂). ② 대부(大夫)의 사당(祠堂). 곧, 일소(一昭)·일목(一穆)과 시조(始祖)를 모신 사당.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三務', '삼무', '춘(春)·하(夏)·추(秋)의 농사일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三無私', '삼무사', '세 가지의 무사(無私). 곧, 천무사복(天無私覆)·지무사재(地無私載)·일월무사조(日月無私照).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三門', '삼문', '① 중앙과 좌우에 정문(正門)과 동협문(東夾門)·서협문(西夾門)의 세 문이 나란히 연하여 한 문을 이룬 대궐(大闕)의 문. ② 사람의 마음씨에 따라 들어가는 데가 다른 세 문. 곧, 금문(禽門)·인문(人門)·성문(聖門). ③ [불교] 절의 본당(本堂) 앞의 다락문. 공문(空門)·무상문(無相門)·무작문(無作門)의 세 해탈문(解脫門)에 비겨 이른 말. 산문(山門). ④ [불교] 지혜문(智慧門)·자비문(慈悲門)·방편문(方便門). ⑤ [불교] 교(敎)·율(律)·선(禪).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三物', '삼물', '① 백성에게 가르치는 세 가지 일. 곧, 육덕(六德)·육행(六行)·육예(六藝). ② 맹약(盟約)을 할 때 피를 쓰기 위하여 잡는 닭·개·돼지.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三民主義', '삼민주의', '손문(孫文)이 제창한 민족주의(民族主義)·민권주의(民權主義)·민생주의(民生主義)의 총칭. 중국 국민당(國民黨)의 지도 정신임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三密', '삼밀', '[불교] 부처의 신밀(身密)〈불신(佛身)의 상(相)〉·구밀(口密)〈입으로 말하는 바〉·의밀(意密)〈마음속에 생각하는 바〉. 모두 비오심밀(秘奧深密)하여 알기 어려우므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三拜', '삼배', '세 번 절함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三百', '삼백', '많은 수를 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三白食', '삼백식', '[불교] 중이 먹는 세 가지 흰 음식. 곧, 젖·타락(醍酪)·밥.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三法司', '삼법사', '명대(明代)의 형옥(刑獄)을 맡은 세 관아(官衙). 곧, 형부(刑部)·도찰원(都察院)·대리시(大理寺).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三辟', '삼벽', '하(夏)·은(殷)·주(周) 삼대(三代)의 형법(刑法). 곧, 하의 우형(禹刑), 은의 탕형(湯刑), 주(周)의 구형(九刑).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三兵', '삼병', '① 세 가지 병기(兵器). 곧, 활·창·칼〔劍〕. ② 세 종류의 전투병. 곧, 보병·포병·기병.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三輔', '삼보', '한무제(漢武帝) 태초 원년(太初元年)에 세 구역으로 나눈 장안(長安) 부근의 땅의 지방 장관. 곧, 장안(長安) 이동(以東)의 경조윤(京兆尹), 장릉(長陵) 이북(以北)의 좌풍익(左馮翊), 위성(渭城) 이서(以西)의 우부풍(右扶風).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三寶', '삼보', '① 도가(道家)에서 이르는 귀·입·눈. ② 토지(土地)·인민(人民)·정치(政治). ③ 자(慈)·검(儉)·겸(謙). ④ [불교] 불보(佛寶)·법보(法寶)·승보(僧寶). 불법승(佛法僧). ⑤ 부처의 별칭(別稱). 불타(佛陀).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三伏', '삼복', '하지(夏至) 후의 셋째 경일(庚日)인 초복(初伏)과 넷째 경일인 중복(中伏)과 입추(立秋) 후의 첫째 경일인 말복(末伏). 복(伏)은 금기복장(金氣伏藏), 곧 가을의 기운인 쇠가 여름의 기운인 불을 무서워하여 엎드려 숨는다는 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三復', '삼복', '여러 번 되풀이함. 자주 되풀이하여 송독(誦讀)함을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三福田', '삼복전', '[불교] 복덕(福德)이 생기는 세 가지 착한 행위. 곧, 삼보(三寶)의 덕(德)을 공경하는 경전(敬田), 부모의 은혜를 갚는 은전(恩田), 빈고(貧苦)를 불쌍하게 여기는 비전(悲田), 또는 부모·사장(師長)을 공경하는 보은복전(報恩福田), 삼보(三寶)를 공경하는 공덕복전(功德福田), 빈궁한 사람을 불쌍히 여기는 빈궁복전(貧窮福田).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三本', '삼본', '천지(天地)와 선조(先祖)와 군사(君師).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三府', '삼부', '① 한대(漢代)의 삼공(三公)의 관부(官府). ② 삼도(三都).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三賦', '삼부', '세 가지 조세(租稅). 곧, 조(租)·용(庸)·조(調).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三部經', '삼부경', '[불교] 특별히 존중하는 세 부(部)의 불경. 정토 삼부경(淨土三部經)을 위시하여 법화(法華)·대일(大日)·진호국가(鎭護國家)·미륵(彌勒) 등 여러 삼부경이 있음. 정토 삼부경은 무량수경(無量壽經)·관무량수경(觀無量壽經)·아미타경(阿彌陀經).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三釜之養', '삼부지양', '박봉(薄俸)을 마다하지 않고 부모를 봉양하기 위하여 벼슬살이를 하는 일. 삼부(三釜)는 엿 말 넉 되.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三分五裂', '삼분오열', '여러 갈래로 갈라짐.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三墳五典', '삼분오전', '고서(古書)의 이름. 삼분(三墳)은 삼황(三皇)의 책이고, 오전(五典)은 오제(五帝)의 책인데, 지금 전하지 않음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三分鼎立', '삼분정립', '천하(天下)를 삼분(三分)하여 서로 대립함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三分鼎足', '삼분정족', '삼분정립(三分鼎立).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三不去', '삼불거', '아내를 내쫓을 수 없는 세 가지 경우. 곧, 아내가 나가서 의지할 곳이 없거나, 부모의 거상(居喪)을 같이 치렀거나, 장가들 때 가난하다가 후에 부귀(富貴)하게 된 경우.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三不祥', '삼불상', '① 나라를 위하여 상서롭지 못한 세 가지 일. 곧, 나라에 어진 이가 있는 것을 모르는 일, 어진 이인 줄 알면서도 등용하지 않는 일, 등용하고서도 신임(信任)하지 않는 일. ② 일신(一身)을 위하여 상서롭지 못한 세 가지 일. 곧, 나이가 어리면서도 연장자를 섬기려고 하지 않는 일, 천(賤)하면서도 귀(貴)한 이를 섬기려고 하지 않는 일, 불초(不肖)하면서도 어진 이를 섬기려고 하지 않는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三不幸', '삼불행', '세 가지 불행한 일. 곧, 소년(少年)에 대과(大科)에 급제하는 일, 부형의 덕으로 미관(美官)을 얻는 일, 고재(高才)가 있어 문장을 잘 짓는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三不惑', '삼불혹', '혹(惑)하지 말아야 할 세 가지. 곧, 음주(飮酒)·여색(女色)·재물(財物)의 삼욕(三欲).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三不孝', '삼불효', '① 맹자(孟子)의 오불효(五不孝) 중의 셋째. 곧, 재화(財貨)를 좋아하고 아내만을 사랑하며 부모의 은혜를 잊는 일. ② 세 가지 불효. 곧, 부모를 불의(不義)에 빠지게 하는 일과, 부모가 늙고 집이 가난하여도 벼슬하지 아니하는 일과, 자식이 없어 세사(世祀)를 끊게 하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三不朽', '삼불후', '영구히 썩지 않는 세 가지. 곧, 입덕(立德)·입공(立功)·입언(立言).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三四', '삼사', '① 셋이나 넷. 적은 수를 이름. ② 서너 번. ③ 서너 개.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三史', '삼사', '세 가지 사서(史書). 곧, 〈사기(史記)〉·〈한서(漢書)〉·〈동관기(東觀記)〉. 〈동관기〉가 산일(散逸)된 후에는 〈후한서(後漢書)〉를 넣음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三司', '삼사', '① 삼공(三公). ② 송(宋)나라의 이재(理財)의 벼슬. 곧, 염철(鹽鐵)·호부(戶部)·탁지(度支). ③ [한국] 조선 시대의 사헌부(司憲府)·사간원(司諫院)·홍문관(弘文館).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三事', '삼사', '① 삼공(三公). ② 임금·부친·스승. 곧, 군(君)·부(父)·사(師)를 섬기는 일. ③ 나라를 다스리는 데 중요한 세 가지 일. 곧, 정덕(正德)·이용(利用)·후생(厚生). ④ 벼슬아치가 지켜야 할 세 가지 중요한 일. 곧, 청렴(淸廉)·근신(謹愼)·근면(勤勉). ⑤ 춘·하·추 삼시(三時)의 농사. 일설(一說)에는, 고원(高原)·저습(低濕)·평지(平地)의 농사라 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三思', '삼사', '① 세 번 생각함. 여러 번 생각함. 숙고(熟考)함. ② 너무 지나치게 생각함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三徙', '삼사', '삼천(三遷).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三赦', '삼사', '주(周)나라 때 죄를 범하여도 형(刑)을 면한 세 종류의 사람. 곧, 일곱 살 이하의 유약자(幼弱者), 여든 살 이상의 노인(老人) 및 천치.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三事戒', '삼사계', '[불교] 몸을 삼가고, 말을 조심하며, 마음을 깨끗이 하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三事大夫', '삼사대부', '삼공(三公)과 경대부(卿大夫). 곧, 공경대부(公卿大夫).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三沙彌', '삼사미', '[불교] 연령별로 나눈 세 가지 사미. 곧, 구오사미(驅烏沙彌)〈일곱 살부터 열세 살까지〉·응법사미(應法沙彌)〈열네 살부터 열아홉 살까지〉·명자사미(名字沙彌)〈이십 세 이상〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三三五五', '삼삼오오', '3~4인 혹은 4~5인씩 떼지어 여기저기 흩어져 있는 모양. 삼삼오오(參參伍伍).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三上', '삼상', '시문(詩文)을 구상하기 좋은 세 곳. 곧, 마상(馬上)·침상(枕上)·측상(廁上).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三象', '삼상', '주공(周公)이 지은 풍류 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三殤', '삼상', '성년(成年)이 되기 전에 죽은 사람의 나이에 따라 구별한 세 가지. 곧, 장상(長殤)〈열여섯 살부터 열아홉 살까지〉·중상(中殤)〈열두 살부터 열다섯 살까지〉·하상(下殤)〈여덟 살부터 열한 살까지〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三生', '삼생', '[불교] 사람이 태어나는 과거·현재·미래의 세상. 곧, 전생(前生)·현생(現生)·후생(後生).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三牲', '삼생', '① 세 가지 희생(犧牲). 곧, 소·양·돼지. ② 미식(美食). 성찬(盛饌).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三生緣分', '삼생연분', '삼생에 걸쳐 끊어질 수 없는 가장 깊은 인연. 곧, 부부간(夫婦間)의 인연.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三善', '삼선', '세 가지 착한 일. 곧, 부자(父子)의 도(道), 군신(君臣)의 의(義), 장유(長幼)의 절(節)〈예절〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三聖', '삼성', '① 복희씨(伏羲氏)·문왕(文王)·공자(孔子). ② 요(堯)·순(舜)·우왕(禹王). ③ 우왕(禹王)·주공(周公)·공자(孔子). ④ 문왕(文王)·무왕(武王)·주공(周公). ⑤ 노자(老子)·공자(孔子)·안자(顔子). ⑥ 노자(老子)·공자(孔子)·석가(釋迦). ⑦ 석가(釋迦)·공자(孔子)·기독(基督). ⑧ [한국] 환인(桓因)·환웅(桓雄)·환검(桓儉).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三聖祠', '삼성사', '[한국] ① 황해도(黃海道) 구월산(九月山)에 있었던 환인(桓因)·환웅(桓雄)·환검(桓儉)을 모신 사당(祠堂). ② 제주도(濟州道) 제주시에 있는 탐라(耽羅)를 개국(開國)한 고(高)·부(夫)·양(良) 삼을나(三乙那)를 제사지내는 신사(神祠).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三世', '삼세', '① 삼대(三代) ①. ② [불교] 과거·현재·미래, 또는 전세(前世)·현세(現世)·내세(來世).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三少', '삼소', '삼고(三孤).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三笑', '삼소', '진(晉)나라의 중 혜원 법사(慧遠法師)가 호계(虎溪)를 건너지 않겠다고 맹세하였는데, 어느 날 찾아온 도연명(陶淵明)·육수정(陸修靜) 두 사람을 배웅하다가 이야기에 정신이 팔려 자기도 모르는 사이에 호계를 건너 버려 세 사람이 대소(大笑)하였다는 고사(故事). 호계삼소(虎溪三笑).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三蘇', '삼소', '북송(北宋)의 삼대 문장가(三大文章家)인 소순(蘇洵)과 그의 아들 소식(蘇軾)·소철(蘇轍) 형제. 순(洵)을 노소(老蘇), 식(軾)을 대소(大蘇), 철(轍)을 소소(小蘇)라고도 하여 구별함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三蘇熟喫羊肉', '삼소숙끽양육', '송(宋)나라 때 삼소(三蘇)의 문장이 널리 애독(愛讀)되었으므로, 그의 문장을 숙독하면 과거(科擧)에 급제하여 양의 고기를 먹을 수 있는 신분(身分)이 된다는 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三損友', '삼손우', '사귀어서 해로운 세 가지 벗. 곧, 편벽(便辟)한 벗, 선유(善柔)한 벗, 편녕(便佞)한 벗. 손자삼우(損者三友).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三獸渡河', '삼수도하', '[불교] 같이 부처의 설법(說法)을 들어도 깨닫는 정도에 심천(深淺)이 있음을 코끼리·말·토끼의 세 짐승이 강을 건너는 데 비유한 말. 곧, 코끼리의 발이 물의 밑바닥까지 닫는 것은 보살(菩薩)에, 말의 발이 물속에 있는 것은 연각(緣覺)에, 토끼의 발이 물 위에 떠 있는 것은 성문(聲聞)에 비유함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三旬', '삼순', '① 상순(上旬)·중순(中旬)·하순(下旬). ② 30일간.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三旬九食', '삼순구식', '30일에 아홉 끼니밖에 못 먹는다는 뜻으로, 가세(家勢)가 지극히 가난함을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三乘', '삼승', '[불교] 성문(聲聞)·연각(緣覺)·보살(菩薩).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三升布', '삼승포', '석새삼베.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尸', '삼시', '삼시충(三尸蟲).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三始', '삼시', '세시(歲始)이고 월시(月始)이며 일시(日始)라는 뜻으로, 정월 초하루의 아침을 이름. 널리 정월 초하루의 뜻으로 쓰임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三施', '삼시', '[불교] 세 가지 보시(布施). 곧 재시(財施)·법시(法施)·무외시(無畏施).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三時', '삼시', '① 농사짓는 데 중요한 세 철. 곧 봄·여름·가을. ② 아침과 낮과 밤. ③ [불교] 정법시(正法時)·상법시(像法時)·말법시(末法時). ④ [불교] 천태종(天台宗)의 종(種)·숙(熟)·탈(脫). 삼시교(三時敎). ⑤ [불교] 법상종(法相宗)의 아함(阿含)·반야(般若)·심밀(深密).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三時敎', '삼시교', '삼시(三時) ④.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三豕金根', '삼시금근', '문자(文字)를 오독(誤讀)·오용(誤用)함을 이름. 기해(己亥)의 자형(字形)을 잘못 보고 삼시(三豕)라고 읽고, 금은(金銀)을 잘못이라 하여 금근(金根)이라고 고친 고사(故事)에서 나온 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三豕渡河', '삼시도하', '문자(文字)를 오독(誤讀)·오용(誤用)함을 이름. 기해도하(己亥渡河)를 삼시도하(三豕渡河)로 잘못 읽은 고사(故事)에서 나온 말. ‘삼시금근(三豕金根)’을 보라.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尸蟲', '삼시충', '도가(道家)에서 이르는, 사람의 배 속에 있는 세 마리의 벌레. 경신(庚申)날 밤에 나와 사람의 음사(陰事)를 천제(天帝)에게 고발한다 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三辰', '삼신', '해·달·별. 일(日)·월(月)·성(星). 삼광(三光).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三身', '삼신', '① [불교] 부처의 본체(本體)인 법신(法身)과, 법신(法身)의 과보(果報)에 의하여 나타나는 중덕원만(衆德圓滿)의 몸인 보신(報身)과, 중생(衆生)을 제도(濟度)하기 위하여 나타나는 몸인 응신(應身). ② 과거·현재·미래의 삼신(三身).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三神', '삼신', '① 천(天)·지(地)·인(人)의 세 신(神). ② [한국] 상고 시대에 조선(朝鮮)의 국토를 열었다는 세 신. 곧, 환인(桓因)·환웅(桓雄)·환검(桓儉).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三神山', '삼신산', '신선(神仙)이 산다는 세 산. 곧, 봉래(蓬萊)·방장(方丈)·영주(瀛洲).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三心', '삼심', '[불교] 삼심구족(三心具足)을 보라.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三心具足', '삼심구족', '[불교] 지성심(至誠心)·심심(深心)·발원심(發願心)을 갖추는 일. 이 삼심을 갖추면 정토(淨土)에 왕생(往生)한다 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十講', '삼십강', '[불교] 법화경(法華經) 28권의 앞에 무량의경(無量義經) 1권과 끝에 보현관경(普賢觀經) 1권을 넣은 30권을 30일간 강(講)하는 일. 조석(朝夕)으로 1권씩 15일간에 강하는 수도 있음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十棒', '삼십봉', '[불교] 선승(禪僧)이 제자를 가르칠 때 곤봉으로 때리는 일. 전(轉)하여, 과오를 알리는 뜻으로 쓰임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十三神', '삼십삼신', '[불교] 관세음보살(觀世音菩薩)의 서른세 가지의 화신(化身).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十三天', '삼십삼천', '[불교] ① 수미산(須彌山) 꼭대기의 네 봉우리에 각각 있는 팔천(八天)과, 중앙에 있어서 이것을 통치하는 제석천(帝釋天). 도리천(忉利天). ② 욕계 육천(欲界六天)·색계 십팔천(色界十八天)·무색계 구천(無色界九天)의 총칭.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十六計', '삼십육계', '서른여섯 가지 꾀. 많은 계책(計策).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十六計不如逃', '삼십육계불여도', '삼십육책주위상계(三十六策走爲上計).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十六宮', '삼십육궁', '한대(漢代)의 궁전(宮殿)의 수. 전(轉)하여, 제왕(帝王)의 궁전의 수.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十六鱗', '삼십육린', '잉어〔鯉〕의 별칭(別稱). 육륙린(六六鱗).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十六策走爲上計', '삼십육책주위상계', '삼십육계 줄행랑이 제일이란 말과 같은 뜻. 곧, 딴 계책을 강구하는 것보다는 우선 도망하여 화를 피한 연후에 방책을 서서히 세우는 것이 제일 상책이라는 말. 전(轉)하여, 비겁한 자를 조소하는 뜻으로 쓰임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十輻共一轂', '삼십폭공일곡', '바퀴의 서른 개의 살이 모두 한 바퀴통에 모여 수레가 달릴 수 있는데, 이 바퀴통은 속이 비었기 때문에 이런 중요한 구실을 할 수 있다는 뜻으로, 군주(君主)는 허공무위(虛空無爲)를 중히 여겨야 한다는 것을 비유한 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三十輻共一轂', '삼십복공일곡', '바퀴의 서른 개의 살이 모두 한 바퀴통에 모여 수레가 달릴 수 있는데, 이 바퀴통은 속이 비었기 때문에 이런 중요한 구실을 할 수 있다는 뜻으로, 군주(君主)는 허공무위(虛空無爲)를 중히 여겨야 한다는 것을 비유한 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三椏', '삼아', '삼지닥나무. 삼아나무. 껍질은 종이의 원료로 쓰임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三惡道', '삼악도', '자기가 한 악업(惡業) 때문에 죽은 후에 가는 곳. 곧, 지옥도(地獄道)·아귀도(餓鬼道)·축생도(畜生道). 삼도(三途).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三惡聲', '삼악성', '세 가지 듣기 싫고 흉한 소리. 곧, 초혼(招魂)하는 소리, 불이 나서 불이야 하고 외치는 소리, 도둑을 튀기는 소리.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三惡趣', '삼악취', '삼악도(三惡道).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三養', '삼양', '복(福)·기(氣)·재(財) 세 가지를 길러 늘리는 일. 곧, 분수(分數)에 만족하고, 위(胃)를 너그럽게 하고 마음을 크게 가지며, 씀씀이를 절약하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三壤', '삼양', '세 가지 전지. 곧, 상전(上田)·중전(中田)·하전(下田).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三業', '삼업', '[불교] ① 신업(身業)·구업(口業)·의업(意業)의 세 가지. ② 탐욕(貪慾)·진에(瞋恚)·우치(愚癡)의 세 가지 죄업(罪業).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三餘', '삼여', '겨울(해의 나머지)과 밤(날의 나머지)과 음우(陰雨)(때의 나머지)로서 학문을 하는 데 가장 좋은 세 가지 여가(餘暇).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三易', '삼역', '삼종(三種)의 역(易). 곧, 하(夏)나라의 연산(連山)과 은(殷)나라의 귀장(歸藏)과 주(周)나라의 주역(周易).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三逆', '삼역', '[불교] 부친·모친·아라한(阿羅漢)을 죽이는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三緣', '삼연', '[불교] 친연(親緣)·근연(近緣)·증상연(增上緣).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三營門', '삼영문', '삼군문(三軍門).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三五', '삼오', '① 삼황오제(三皇五帝)를 이름. ② 삼신(三辰)과 오성(五星). ③ 삼신(三辰)과 오행(五行). ④ 30세와 500세. 30세에 조금 변하고, 500세에 크게 변함. ⑤ 삼심 오주(三心五噣), 곧, 심(心)·유(柳)의 두 성수(星宿). ⑥ 음력 보름날. ⑦ 음력 보름날 밤. 또, 음력 팔월 보름날 밤.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三五之隆', '삼오지륭', '삼황오제(三皇五帝) 시대의 융성(隆盛)한 세상.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三五七言詩', '삼오칠언시', '한 구(句) 중에 삼언구(三言句) 둘과 오언구(五言句) 둘과 칠언구(七言句) 둘을 갖춘 시(詩). 예컨대, 이백(李白)의 ‘秋風淸, 秋月明, 落葉聚還散, 寒鴉棲復驚, 相思相見知何日, 此時此夜難爲情’.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三瓦戒', '삼와계', '지붕을 이는데 일부러 기와 석 장을 모자라게 하여 충족(充足)을 경계하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三澣', '삼완', '삼한(三澣).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三王', '삼왕', '하(夏)나라의 우왕(禹王)과 은(殷)나라의 탕왕(湯王)과 주(周)나라의 문왕(文王)·무왕(武王). 문왕과 무왕은 부자(父子)이므로 한 임금으로 봄.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三畏', '삼외', '군자(君子)가 두려워하여 삼가야 할 세 가지 일. 곧, 천명(天命)·대인(大人)·성인지언(聖人之言).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三慾', '삼욕', '[불교] 세 가지 욕심. 곧, 음식욕(飮食慾)·수면욕(睡眠慾)·음욕(淫慾).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三浴三薰', '삼욕삼훈', '몸에 자주 향(香)을 바르고 자주 목욕을 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三友', '삼우', '① 유익한 세 종류의 벗. ‘삼익우(三益友)’를 보라. 또, 해로운 세 종류의 벗. ‘삼손우(三損友)’를 보라. ② 거문고·술·시. 금(琴)·주(酒)·시(詩). ③ 소나무·대나무·매화나무. 송(松)·죽(竹)·매(梅). 세한삼우(歲寒三友). ④ 산수(山水)·난죽(蘭竹)·금주(琴酒).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三虞', '삼우', '장사(葬事) 지낸 후 세 번째 지내는 제사(祭祀).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三元', '삼원', '① 천(天)·지(地)·인(人) 삼재(三才). ② 정월 초하루. 삼시(三始). ③ 정월 보름인 상원(上元)과 칠월 보름인 중원(中元)과 시월 보름인 하원(下元). ④ 진사(進士)〈중국의 대과(大科)〉에 삼 등 안으로 급제한 세 사람. 또, 향시(鄕試)·회시(會試)·정시(廷試)에 수석을 차지한 사람. 곧, 해원(解元)·회원(會元)·장원(狀元).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三垣', '삼원', '상원(上垣)·중원(中垣)·하원(下垣)의 총칭. 고대의 천문학에서 북극(北極)을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三怨', '삼원', '사람에게 원망을 당하는 세 가지. 곧, 작위(爵位)가 높으면 사람에게 원망을 당하고, 관직(官職)이 크면 임금에게 원망을 당하며, 녹(祿)이 후하여도 원망을 당함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三願', '삼원', '세 가지 소원. 곧, 세상의 호인(好人)·호서(好書)·호산수(好山水)를 모두 알고자 하는 소원.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三位一體', '삼위일체', '① [불교] 부처는 법신(法身)·응신(應身)·보신(報身)의 삼위(三位)로 구분되나, 본래는 일체라는 뜻. ② 기독교(基督敎)에서 성부(聖父)·성자(聖子)·성령(聖靈)의 삼위(三位)를 한 몸으로 보는 교의(敎義).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三宥', '삼유', '① 주대(周代)에 죄를 용서하는 세 가지 조건. 곧, 불식(不識)·과실(過失)·유망(遺亡). ② 왕족(王族)이 죄를 범하였을 때 왕이 세 번 용서한 뒤에 형을 과하는 법.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三揖一辭', '삼읍일사', '군자(君子)는 벼슬길에 나아가는 데는 신중(愼重)하고, 벼슬을 물러나는 데는 간이(簡易)하다는 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三衣', '삼의', '[불교] 중이 입는 세 가지 가사(袈裟). 곧, 대의(大衣)·칠조(七條)·오조(五條).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三宜休', '삼의휴', '사람이 마땅히 쉬어야 할 세 가지 경우. 재주가 얼마나 있나 헤아리고, 제 분수에 맞나 헤아리고, 늙어서 귀가 먹었을 때를 이름. 당(唐)의 사공도(司空圖)의 고사에서 온 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三易', '삼이', '문장을 쉽게 짓는 세 가지 방법. 곧, 보기 쉽게 쓰고, 쉬운 자를 쓰며, 읽기 쉽게 씀.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三益', '삼익', '삼익우(三益友).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三益友', '삼익우', '① 사귀어서 자기에게 도움이 되는 세 가지 벗. 곧, 곧은 벗, 믿음직한 벗, 문견이 많은 벗. 익자삼우(益者三友). 삼우(三友). ② 화제(畵題)에서 쓰는 말로 매화(梅花)나무·대나무·돌의 일컬음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三益主義', '삼익주의', '영업 단체의 이익은 자본가와 경영자와 노동자가 삼분(三分)하여야 한다는 주장.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三仁', '삼인', '은(殷)나라 말년의 세 사람의 충신(忠臣). 곧, 미자(微子)·기자(箕子)·비간(比干).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三人成市虎', '삼인성시호', '한두 사람이 거리에 범이 있다고 말하면 곧이듣지 않으나, 세 사람까지 그렇게 말하면 곧이듣는다는 뜻으로, 무근(無根)한 일도 이야기하는 사람이 많으면 자연히 믿게 됨을 비유한 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三人爲一龍', '삼인위일룡', '세 사람의 극친한 벗의 비유.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三人行必有我師', '삼인행필유아사', '자기와 딴 두 사람이 일을 같이할 때에는 선악간(善惡間)에 반드시 스승으로서 배울 만한 사람이 있음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日哭', '삼일곡', '① 사흘 동안 곡함. 사당(祠堂)이 탔을 때의 예(禮)임. ② 오랫동안 곡함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日僕射', '삼일복야', '진(晉)나라 사람 주의(周顗)가 상서성(尙書省)의 장관(長官)인 복야(僕射)가 되었을 때 주야로 술만 마시고 정사(政事)는 돌보지 않은 고사(故事). ‘삼일’은 집정(執政)한 날이 적다는 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日不讀書語言無味', '삼일부독서어언무미', '불과 3일간이라도 독서를 하지 않으면 마음이 비열(卑劣)하여져서 하는 말도 자연히 아치(雅致)가 없다는 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日不飮酒覺形神不相親', '삼일불음주각형신불상친', '사흘 동안 술을 마시지 않으면 육체와 정신이 서로 떨어진 것과 같은 심경(心境)이라는 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日三夜', '삼일삼야', '삼주야(三晝夜).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日雨', '삼일우', '사흘 동안 계속하여 내리는 비.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日葬', '삼일장', '죽은 지 사흘 만에 지내는 장사.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日點考', '삼일점고', '[한국] 수령(守令)이 부임한 지 사흘 만에 관속(官屬)을 점고하는 일.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三日天下', '삼일천하', '짧은 동안 정권(政權)을 잡았다가 곧 축출당함을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三子', '삼자', '① 노자(老子)·장자(莊子)·열자(列子). ② 맹자(孟子)·순자(荀子)·양자(揚子).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三長', '삼장', '사가(史家)가 되는 데 필요한 세 가지 장점. 곧, 재지(才智)·학문(學問)·식견(識見).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三章', '삼장', '① 한고조(漢高祖)가 제창한 세 조목의 법률. ② 간명한 규칙.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三障', '삼장', '[불교] 정도(正道)와 선심(善心)을 방해하는 세 가지 장애(障礙). 곧, 번뇌장(煩惱障)·업장(業障)·보장(報障).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三藏', '삼장', '[불교] ① 불타(佛陀)의 설법(說法)을 결집(結集)한 경장(經藏)과, 승속(僧俗)의 계율(戒律)과 위의(威儀)를 결집한 율장(律藏)과, 교리(敎理)의 논석(論釋)을 모은 논장(論藏)의 세 가지. 또, 이에 통효(通曉)한 고승(高僧). ② 성문장(聲聞藏)·연각장(緣覺藏)·보살장(菩薩藏). ③ 천태종(天台宗)에서 소승(小乘)의 별칭(別稱).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三才', '삼재', '① 하늘과 땅과 사람. 천(天)·지(地)·인(人). ② 천지간(天地間)의 만물. ③ 세 사람의 재사(才士).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三災', '삼재', '[불교] ① 수재(水災)·화재(火災)·풍재(風災). ② 도병재(刀兵災)·질병재(疾病災)·기근재(飢饉災).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三災八難', '삼재팔난', '삼재(三災)와 팔난(八難). 곧, 모든 재난.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三傳', '삼전', '공자(孔子)가 저술한 춘추(春秋)의 세 가지 해설서(解說書). 곧, 〈좌씨전(左氏傳)〉·〈공양전(公羊傳)〉·〈곡량전(穀梁傳)〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三戰三北', '삼전삼배', '세 번 싸워 세 번 패배함. 자주 싸움에 패(敗)함. 삼전 삼패(三戰三敗).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三戰三走', '삼전삼주', '세 번 싸우고 세 번 패하여 달아남.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三戰神', '삼전신', '[불교] 전쟁을 맡은 세 신(神). 곧, 마리지천(摩利支天)·대흑천(大黑天)·비사문천(毘沙門天).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三絶', '삼절', '① 세 번 끊어짐. ② 세 가지의 뛰어난 일, 또는 재주.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三折肱爲良醫', '삼절굉위양의', '쓰라린 경험을 여러 번 겪어야만 명의(名醫)가 됨.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三正', '삼정', '① 천(天)·지(地)·인(人) 삼재(三才)의 정도(正道). ② 군신(君臣)·부자(父子)·부부(夫婦)의 도(道)인 삼강(三綱)이 바름. ③ 역법(曆法)의 술어(術語)로서, 하(夏)·은(殷)·주(周) 삼대(三代)의 달력, 또는 자(子)·축(丑)·인(寅)의 일컬음. 하(夏)나라의 달력은 인(寅)의 달을, 은(殷)나라의 달력은 축(丑)의 달을, 주(周)나라의 달력은 자(子)의 달을 정월(正月)로 하였으므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三精', '삼정', '해·달·별. 일(日)·월(月)·성(星).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三諦', '삼제', '[불교] 천태종(天台宗)에서 말하는 세 가지 진리. 곧, 제법(諸法)을 모두 공(空)이라고 보는 공제(空諦)와, 제법을 모두 유(有)라고 보는 가제(假諦)와, 공도 아니고 유도 아니라고 보는 중제(中諦). 제(諦)는 진리(眞理).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三諦卽是', '삼제즉시', '삼제(三諦)는 하나이면서도 셋이고, 셋이면서도 하나임.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三朝', '삼조', '① 삼시(三始). ② 초사흗날 아침. ③ 주대(周代)의 내조(內朝)〈천자가 휴식하는 곳〉·치조(治朝)〈천자가 정사(政事)를 보는 곳〉·외조(外朝)〈군신(君臣)이 회의하는 곳〉. ④ 삼대(三代)의 왕조(王朝). 또, 삼대의 군주(君主). ⑤ 세 번의 입조(入朝). 공자(孔子)가 노(魯)나라에서 세 번 벼슬한 것을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三條椽下', '삼조연하', '[불교] 선당(禪堂) 안의 한 사람이 앉을 만한 자리를 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三族', '삼족', '① 부모·형제·처자. ② 부친·아들·손자. 부(父)·자(子)·손(孫). ③ 부친의 곤제(昆弟), 자기의 곤제, 아들의 곤제. ④ 부족(父族)·모족(母族)·처족(妻族).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三足烏', '삼족오', '① 해 속에 산다는 세 발 가진 까마귀. ② 태양(太陽)의 별칭.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尊', '삼존', '① 존앙(尊仰)하여야 할 세 사람. 곧, 군주·부친·스승. 군(君)·부(父)·사(師). ② [불교] 미타(彌陀)·관음(觀音)·세지(勢至). 미타 삼존(彌陀三尊). ③ [불교] 석가(釋迦)·문수(文殊)·보현(普賢). 석가 삼존(釋迦三尊). ④ [불교] 약사여래(藥師如來)·일광천(日光天)·월광천(月光天). 약사 삼존(藥師三尊).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尊來迎', '삼존내영', '[불교] 미타(彌陀)·관음(觀音)·세지(勢至)의 삼존(三尊)이 출현하여 정토(淨土)로 인도함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三宗', '삼종', '[불교] 세 종파(宗派). 곧, 화엄종(華嚴宗)·삼론종(三論宗)·법상종(法相宗), 또는 천태종(天台宗)·진언종(眞言宗)·법상종(法相宗).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三從', '삼종', '① 여자가 지켜야 할 세 가지 도덕. 곧, 어렸을 때에는 어버이를, 시집가서는 남편을, 남편을 여읜 뒤에는 아들을 좇는 일. 삼종지의(三從之義). ② 삼종형제(三從兄弟).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三種世間', '삼종세간', '[불교] 중생세간(衆生世間)·국토세간(國土世間)·오온세간(五蘊世間).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三從兄弟', '삼종형제', '고조(高祖)가 같고 증조(曾祖)가 다른 형제. 팔촌(八寸).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三晝夜', '삼주야', '만 3일. 삼일삼야(三日三夜).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三知', '삼지', '천분(天分)의 고하(高下)로 인한 도(道)를 깨닫는 힘의 세 층등(層等). 곧, 태어나면서부터 아는 생지(生知)와, 배워서 아는 학지(學知)와, 애써서 아는 곤지(困知).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三智', '삼지', '[불교] 부처의 슬기의 세 구분. 곧, 진여(眞如)를 해득(解得)하는 진지(眞智)와, 무명(無明)을 깨닫는 내지(內智)와, 세사(世事)에 통효(通曉)하는 외지(外智).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三旨相公', '삼지상공', '무능한 재상을 조소(嘲笑)하는 말. 우리나라의 ‘지당 대신’과 뜻이 같음. 송(宋)나라의 재상(宰相) 왕규(王珪)가 일(一)에도 성지(聖旨)가 지당하고, 이(二)에도 성지가 지당하며, 삼(三)에도 성지가 지당하다고 하여 무슨 일에나 천자(天子)의 뜻만 좇은 고사(故事)에 의함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三枝之禮', '삼지지례', '비둘기는 예의를 지켜 어미새가 앉은 가지에서 세 가지 아래 되는 데 앉는다는 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三枝槍', '삼지창', '끝이 세 갈래 진 창(槍).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三秦', '삼진', '① 옹(雍)·새(塞)·적(翟)의 세 나라. 항우(項羽)가 진(秦)나라를 멸(滅)하고 그 영토를 나누어 진나라의 항장(降將) 장한(章邯)·사마흔(司馬欣)·동예(董翳)를 왕으로 봉(封)하였으므로 이름. ② 십육국 시대(十六國時代)의 전진(前秦)·후진(後秦)·서진(西秦)의 세 나라.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三晉', '삼진', '전국 시대(戰國時代)의 한(韓)·위(魏)·조(趙)의 세 씨(氏). 이들의 선조(先祖)는 본시 진(晉)나라를 섬겼는데, 후에 진나라를 분할하여 각각 독립하였으므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三徵七辟', '삼징칠벽', '세 번 천자(天子)가 부르고 일곱 번 주군(州郡)에서 부른다는 뜻으로, 자주 임관시키려고 조정에서나 지방 관아(地方官衙)에서 부름을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三叉', '삼차', '세 갈래.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三車', '삼차', '양차(羊車)·녹차(鹿車)·우차(牛車).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三車', '삼거', '양차(羊車)·녹차(鹿車)·우차(牛車).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三倉', '삼창', '자서(字書)의 총칭(總稱). 한대(漢代)에는 창힐편(倉頡篇)·원력편(爰歷篇)·박학편(博學篇)을 이르고, 위진(魏晉) 이후에는 창힐편(倉頡篇)·훈찬편(訓纂篇)·방희편(滂喜篇)도 일컬음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尺', '삼척', '① 삼척법(三尺法). ② 칼. 검(劍). 길이가 석 자이므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尺童子', '삼척동자', '대여섯 살의 어린아이.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尺法', '삼척법', '법. 법률. 옛날에 길이가 석 자 되는 죽찰(竹札)에 법문(法文)을 적었으므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三尺秋水', '삼척추수', '서슬이 시퍼런 칼. 삼척(三尺)은 칼의 길이, 추수(秋水)는 칼의 빛을 형용한 말.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三天', '삼천', '[불교] 마리지천(摩利支天)·대흑천(大黑天)·변재천(辨財天).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三遷', '삼천', '삼천지교(三遷之敎).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三千大千世界', '삼천대천세계', '[불교] ① 소천세계(小千世界)·중천세계(中千世界)·대천세계(大千世界)의 총칭(總稱). 수미산(須彌山)을 중심으로 하여 해와 달과 사천하(四天下)를 한 세계라 이르고, 이것을 천 배한 것을 소천세계(小千世界), 소천세계를 천 배한 것을 중천세계(中千世界), 중천세계를 천 배한 것을 대천세계(大千世界)라 함. 삼천 세계(三千世界). ② 전 세계. 넓은 세계.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三千世界', '삼천세계', '삼천 대천세계(三千大千世界).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三遷之敎', '삼천지교', '맹자(孟子)의 어머니가 맹자를 가르치기 위하여 집을 세 번 옮긴 일. 좋은 환경을 택하기 위하여 처음에 묘지(墓地) 옆에서 살다가 저잣거리로, 저잣거리에서 또 학교 옆으로 옮겼음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三千寵愛', '삼천총애', '여러 시녀(侍女)가 받는 총애.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三淸', '삼청', '도교(道敎)에서 옥청(玉淸)·상청(上淸)·태청(太淸)을 이름(신선이 산다는 궁의 이름).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三諦', '삼체', '삼제(三諦).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三體', '삼체', '① 세 가지 체형(體形). ② 진(眞)·행(行)·초(草)의 세 서체(書體). ③ 고체(固體)·액체(液體)·기체(氣體).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三體詩', '삼체시', '송말(宋末)에 주필(周弼)이 당대(唐代)의 시인 167인의 시를 칠언 절구(七言絶句)·칠언 율시(七言律詩)·오언 율시(五言律詩)의 삼체(三體)로 나누어 편찬한 시집. 총 6권.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三焦', '삼초', '한방(漢方)에서 이르는 육부(六腑)의 하나로서 상초(上焦)·중초(中焦)·하초(下焦)의 총칭. 상초는 심장 아래에, 중초는 위(胃) 속에, 하초는 방광(膀胱) 위에 있어서 수분(水分)의 배설(排泄)을 맡는다고 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三寸不律', '삼촌불률', '붓〔筆〕의 별칭(別稱). 삼촌(三寸)은 붓의 길이. 불률(不律)의 합음(合音)은 필(筆).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三寸舌', '삼촌설', '① 혀. 삼촌(三寸)은 혀의 길이. ② 언어(言語)·변설(辯舌)을 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三秋', '삼추', '① 가을의 3개월. 곧, 음력 7월의 초추(初秋), 음력 8월의 중추(仲秋), 음력 9월의 만추(晩秋). ② 9개월. 춘·하·추·동은 각각 3개월씩이므로 이름. 삼계(三季). ③ 3개년. 3개년 동안에 가을이 세 번 돌아오므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三秋之思', '삼추지사', '하루만 만나지 않아도 3년 동안이나 만나지 않은 것같이 생각된다는 뜻으로, 사람을 사모하는 마음이 대단히 간절함을 이름. 일설(一說)에, 삼추(三秋)는 9개월. 일일삼추(一日三秋).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三春', '삼춘', '① 봄의 3개월. 곧, 음력 정월의 맹춘(孟春), 음력 2월의 중춘(仲春), 음력 3월의 계춘(季春). ② 3개년. 3개년 동안에 봄이 세 번 돌아오므로 이름. 삼추(三秋).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三蟲', '삼충', '삼시충(三尸蟲).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三層樓', '삼층루', '삼 층의 건물.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三致意', '삼치의', '깊이 마음을 씀. 대단히 관심을 둠.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三親', '삼친', '① 부자(父子)·부부(夫婦)·형제(兄弟). ② 부족(父族)·모족(母族)·처족(妻族).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三七日', '삼칠일', '해산(解産)한 지 스무하루 되는 날.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三嘆', '삼탄', '여러 번 찬탄(讚嘆)함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三台', '삼태', '① 자미궁(紫微宮)의 주위에 있는 상태(上台)·중태(中台)·하태(下台)의 각각 두 별씩 도합 여섯 별. ② 삼공(三公)의 뜻.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三台星', '삼태성', '삼태(三台) ①.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三宅', '삼택', '‘삼택삼준(三宅三俊)’을 보라.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三宅三俊', '삼택삼준', '삼택(三宅)은 상백(常伯)·상임(常任)·준인(準人)의 지위. 삼준(三俊)은 삼택이 될 만한 덕(德)이 있는 사람.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三通', '삼통', '이름에 통(通)의 글자가 든 세 책. 곧, 당(唐)나라 사람 두우(杜佑)가 지은 〈통전(通典)〉, 송(宋)나라 사람 정초(鄭樵)가 지은 〈통지(通志)〉, 송나라 사람 마단림(馬端臨)이 지은 〈문헌통고(文獻通考)〉.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三巴', '삼파', '파(巴)라는 글자가 든 세 고을. 후한(後漢)의 파(巴)·파동(巴東)·파서(巴西)를 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三品', '삼품', '그림의 세 가지 품위. 곧, 신품(神品)·묘품(妙品)·능품(能品).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三風十愆', '삼풍십건', '세 가지 나쁜 풍습. 곧, 무풍(巫風)·음풍(淫風)·난풍(亂風)과 그 세목(細目)인 열 가지 허물. 곧, 항무(恒舞)·감가(酣歌)·순화(殉貨)·순색(殉色)·항유(恒遊)·항전(恒畋)·모성언(侮聖言)·역충직(逆忠直)·원기덕(遠耆德)·비완동(比頑童).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三河', '삼하', '① 황하(黃河)·회하(淮河)·낙하(洛河). ② 한대(漢代)의 하내(河內)·하남(河南)·하동(河東)의 세 군(郡)을 이름. ③ 황하(黃河) 하동·하남·하북의 세 군을 흐르므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三夏', '삼하', '① 여름의 3개월. 곧, 음력 4월의 맹하(孟夏), 음력 5월의 중하(仲夏), 음력 6월의 계하(季夏). 구하(九夏). ② 3개년. 3개년 동안에 여름이 세 번 돌아오므로 이름.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三學', '삼학', '① 당대(唐代)의 국자학(國子學)·태학(太學)·사문학(四門學). 송대(宋代)에는 태학을 외사(外舍)·내사(內舍)·상사(上舍)로 나누어 이를 삼학이라 하였음. ② 문학(文學)·무학(武學)·종학(宗學). ③ [불교] 수업승(修業僧)이 닦아야 할 세 가지 학문. 곧, 계학(戒學)·정학(定學)·혜학(慧學).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三澣', '삼한', '달의 상·중·하순의 일컬음. 한(澣)은 본래 씻는다는 뜻이나 한당(漢唐)의 제도에, 관리는 열흘마다 휴가를 얻어 목욕하였으므로, 전(轉)하여 십 일의 뜻으로 쓰임. 삼순(三旬). 삼완(三澣).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三韓', '삼한', '[한국] 전한(前漢) 초에 우리나라 남부에 일어난 세 나라. 곧, 마한(馬韓)·진한(辰韓)·변한(弁韓).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三寒四溫', '삼한사온', '겨울철에 한국·만주 등지에서 사흘가량 추운 날씨가 계속되다가 그 다음에 나흘가량 따스한 날씨가 계속되는 주기적(週期的)인 기후 현상.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三解脫', '삼해탈', '세 가지 해탈(解脫). 곧, 공(空)·무상(無想)·무원(無願).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三行', '삼행', '① 자식으로서 어버이에게 행하여야 할 세 가지 행위. 곧, 양친(養親)·치상(治喪)·봉제사(奉祭祀). ② 사람이 중히 여겨야 할 세 가지 행위. 곧, 부모를 섬기는 효행(孝行), 군자(君子)를 존경하는 우행(友行), 사장(師長)을 섬기는 순행(順行).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三革', '삼혁', '① 가죽으로 만드는 세 가지 무기. 곧, 갑옷·투구·방패. ② 개원(改元)의 이유가 된 세 혁명. 곧, 갑자혁명(甲子革命)·무진혁명(戊辰革命)·신유혁명(辛酉革命).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三絃', '삼현', '삼현금(三絃琴).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三賢', '삼현', '[불교] 대승(大乘)의 십주(十住)·십행(十行)·십회향(十回向)의 세 보살(菩薩).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三絃琴', '삼현금', '줄 셋을 맨 거문고.</br></br>![삼현금](img/hanja_20261118082439.png)', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三峽', '삼협', '촉(蜀) 땅의 세 협곡(峽谷). 곧, 무협(巫峽)·구당협(瞿塘峽)·서릉협(西陵峽). 일설(一說)에는, 서릉협·귀향협(歸鄕峽)·무협(巫峽).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三慧', '삼혜', '[불교] 세 가지 지혜. 곧, 견문하여 얻는 문혜(聞慧), 사유(思惟)하여 얻는 사혜(思慧), 수행(修行)하여 얻는 수혜(修慧).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三壺', '삼호', '해중(海中)에 있는 신선(神仙)이 산다는 세 산. 곧, 봉호(蓬壺)·방호(方壺)·영호(瀛壺). 산의 모양이 병과 같다 하여 이른 말. 삼신산(三神山). 삼도(三島).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三魂', '삼혼', '[불교] ① 사람의 몸 가운데 있는 세 가지 정혼(精魂). 곧, 태광(台光)·상령(爽靈)·유정(幽精). ② 업상(業相)·전상(轉相)·현상(現相).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三桓', '삼환', '춘추 시대(春秋時代)의 노(魯)나라의 삼경(三卿). 곧, 맹손씨(孟孫氏)·계손씨(季孫氏)·숙손씨(叔孫氏). 모두 환공(桓公)의 자손이므로 이름. 삼가(三家).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三皇', '삼황', '중국 고대의 천자(天子). 곧, 복희씨(伏羲氏)·신농씨(神農氏)·황제(黃帝), 또는 수인씨(燧人氏). 일설(一說)에는, 포희씨(包犧氏)·여와씨(女媧氏)·신농씨(神農氏), 또 일설에는, 천황씨(天皇氏)·지황씨(地皇氏)·인황씨(人皇氏).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三皇五帝', '삼황오제', '삼황(三皇)과 오제(五帝). 오제는 소호(少昊)·전욱(顓頊)·제곡(帝嚳)·요(堯)·순(舜). 〈사기(史記)〉에는 소호(少昊) 대신 황제(黃帝)로 되어 있음.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三會', '삼회', '[불교] ① 미륵(彌勒)이 나타나 용화수(龍華樹) 밑에서 세 번 설법(說法)하는 일. 이를 용화삼회(龍華三會)라 함. ② 흥복사(興福寺)의 유마회(維摩會), 약사사(藥師寺)의 최승회(最勝會), 금중(禁中)의 어재회(御齋會). 이를 남경(南京)의 삼회(三會)라 함. ③ 원종사(圓宗寺)의 법화회(法華會)·최승회(最勝會), 법승사(法勝寺)의 대승회(大乘會). 이를 북경(北京)의 삼회라 함.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三回忌', '삼회기', '[불교] 3년째의 기일(忌日). 대상(大祥) 날. 대상기(大祥忌).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三孝', '삼효', '세 가지 효행. 곧, 첫째는 존친(尊親), 둘째는 불욕(弗辱), 셋째는 능양(能養).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三釁三浴', '삼흔삼욕', '삼욕삼훈(三浴三薰).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('三犧', '삼희', '삼생(三牲).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('下', '하', '[자해]</br>①아래 하 ㉠위의 대(對). ‘上下’, ‘下層’. ‘下臨無地’〈王勃〉. ㉡낮은 곳. ‘猶水之就下’〈孟子〉. ㉢밑. 바닥. ‘地下’. ‘出魚乎十仞之下’〈呂氏春秋〉. ㉣물건의 머리와 반대되는 쪽 끝. ‘下文’. ‘若河決下流而東注’〈韓愈〉. ㉤뒤. 후세. ‘千歲之下’〈歷代名畵記〉. ‘上自唐虞, 下至秦繆’〈十八史略〉. ㉥열등. ‘下劣’. ‘厥賦下上’〈書經〉. ㉦두 사물(事物) 중의 경(輕)한 쪽. ‘上以安主體, 下以便萬民’〈漢書〉. ㉧낮은 지위. 낮은 사람. ‘下嫁’. ‘在下不怨’〈孝經〉. ㉨부하. ‘手下’. ‘强將之下無弱兵’〈蘇軾〉. ㉩백성. 서민. ‘上之化下, 得其道’〈韓愈〉. ㉪곁. 가. ‘數州之土壤, 皆在衽席之下’〈柳宗元〉. ㉫산기슭. ‘采苦采苦, 首陽之下’〈詩經〉. ㉬땅. ‘禱爾于上下神祇’〈論語〉. ㉭어의(語意)를 강하게 하기 위하여 조사(助辭)와 같이 씀. ‘但見古來盛名下, 終日坎壈纏其身’〈杜甫〉. ㉮자기의 사물에 관한 겸칭(謙稱). ‘下懷’. ‘下走將歸延陵之墓’〈漢書〉.</br>②낮을 하 아래임. 미치지 못함. ‘下位’, ‘下等’. ‘下王后一等’〈詩經序〉.</br>③내릴 하 ㉠낮은 데로 옮음. 내려감. ‘下車’, ‘下山’. ‘浮西河而下’〈史記〉. 또, 낮은 데로 옮김. ‘糟糠之妻不下堂’〈後漢書〉. ㉡비가 옴. ‘陰雲噎兮雨未下’〈曹丕〉. 또, 비가 오게 함. ‘天油然作雲, 沛然下雨’〈孟子〉. ㉢명령이 나옴. ‘制下’〈十八史略〉. 또, 명령을 냄. ‘下命’. ‘趣使使下令’〈史記〉. ㉣착수함. 손을 댐. ‘下手’. ‘將軍下筆開生面’〈杜甫〉.</br>④떨어질 하 ㉠낙하함. ‘慷慨傷懷, 泣數行下’〈史記〉. ㉡함락함. 항복함. ‘齊城不下者兩城耳’〈史記〉.</br>⑤떨어뜨릴 하 함락시킴. 항복받음. ‘憑軾下東藩’〈魏徵〉.</br>⑥낮출 하 ㉠겸손함. ‘卑下’. ‘以貴下賤, 大得民也’〈易經〉. ㉡감함. 적게 함. ‘歲登下其損益之數’〈周禮〉.</br></br>[자원] (지사(指事))</br>갑골문(甲骨文)·금문(金文)·고문(古文)은 기준(基準)되는 가로획 밑에 짧은 가로획을, 전문(篆文)은 기준되는 가로획 밑에 긴 세로획을 긋고, ‘밑·아래’의 뜻을 나타냄.', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('下嫁', '하가', '군주(君主)의 딸이 신하(臣下)에게 시집감. 하강(下降).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('下疳', '하감', '성병(性病)의 한 가지. 음식창(陰蝕瘡). 감창(疳瘡).', '2026-11-17T23:44:29+00:00'::timestamptz),
  ('下瞰', '하감', '내려다봄. 부감(俯瞰).', '2026-11-17T23:44:29+00:00'::timestamptz),
